export const getListerHeuresUrl = (params?: ListerHeuresParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/heures?${stringifiedParams}`
    : `/api/heures`;
};

export const listerHeures = async (
  params?: ListerHeuresParams,
  options?: RequestInit,
): Promise<Heure[]> => {
  return customFetch<Heure[]>(getListerHeuresUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getListerHeuresQueryKey = (params?: ListerHeuresParams) => {
  return [`/api/heures`, ...(params ? [params] : [])] as const;
};

